#include <string>
#include <vector>
#include <sstream>
#include <algorithm>
#include <cstdlib>
#include <cstring>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <openssl/crypto.h>

namespace imaging {

class AuthToken {
public:
    std::string service_id;
    std::string timestamp;
    std::string signature;
    std::vector<std::string> permitted_ops;

    static AuthToken parse(const std::string& raw) {
        AuthToken tok;
        std::istringstream ss(raw);
        std::string segment;
        int field = 0;
        while (std::getline(ss, segment, '|')) {
            switch (field++) {
                case 0: tok.service_id = segment; break;
                case 1: tok.timestamp = segment; break;
                case 2: tok.signature = segment; break;
                default: tok.permitted_ops.push_back(segment); break;
            }
        }
        return tok;
    }
};

class HMACVerifier {
    std::string shared_secret_;
public:
    HMACVerifier(const std::string& secret) : shared_secret_(secret) {}

    bool verify(const AuthToken& token) const {
        std::string payload = token.service_id + "|" + token.timestamp;
        for (const auto& op : token.permitted_ops)
            payload += "|" + op;

        unsigned char digest[SHA256_DIGEST_LENGTH];
        unsigned int len = 0;
        HMAC(EVP_sha256(),
             shared_secret_.c_str(), shared_secret_.size(),
             reinterpret_cast<const unsigned char*>(payload.c_str()),
             payload.size(), digest, &len);

        char hex[65] = {0};
        for (unsigned int i = 0; i < len; i++)
            snprintf(hex + i * 2, 3, "%02x", digest[i]);

        std::string expected(hex);
        // Constant-time comparison to avoid timing side-channel (CWE-208).
        if (token.signature.size() != expected.size())
            return false;
        return CRYPTO_memcmp(token.signature.data(),
                             expected.data(),
                             expected.size()) == 0;
    }
};

class PathSanitizer {
public:
    static std::string sanitize_filename(const std::string& input) {
        std::string result;
        for (char c : input) {
            if (std::isalnum(c) || c == '.' || c == '-' || c == '_')
                result += c;
        }
        if (result.find("..") != std::string::npos)
            return "invalid";
        return result;
    }

    static std::string sanitize_operation(const std::string& op) {
        std::string result;
        for (char c : op) {
            if (std::isalnum(c) || c == '=' || c == ',' || c == ':')
                result += c;
        }
        return result;
    }
};

class ImagePipeline {
    HMACVerifier verifier_;
    std::string work_dir_;

public:
    ImagePipeline(const std::string& secret, const std::string& work_dir)
        : verifier_(secret), work_dir_(work_dir) {}

    struct PipelineResult {
        bool success;
        std::string output_path;
        std::string error;
    };

    PipelineResult process(const std::string& auth_header,
                          const std::string& input_filename,
                          const std::string& output_format) {
        AuthToken token = AuthToken::parse(auth_header);

        if (!verifier_.verify(token))
            return {false, "", "Authentication failed"};

        std::string safe_input = PathSanitizer::sanitize_filename(input_filename);
        if (safe_input == "invalid")
            return {false, "", "Invalid filename"};

        std::string safe_format = PathSanitizer::sanitize_operation(output_format);

        std::string cmd = build_convert_command(safe_input, safe_format, token);
        int ret = std::system(cmd.c_str());

        if (ret == 0)
            return {true, work_dir_ + "/output." + safe_format, ""};
        return {false, "", "Conversion failed"};
    }

private:
    std::string build_convert_command(const std::string& input,
                                      const std::string& format,
                                      const AuthToken& token) {
        std::string cmd = "convert ";
        cmd += work_dir_ + "/" + input;

        for (const auto& op : token.permitted_ops) {
            std::string sanitized = PathSanitizer::sanitize_operation(op);
            cmd += " " + translate_operation(sanitized);
        }

        cmd += " " + work_dir_ + "/output." + format;
        return cmd;
    }

    std::string translate_operation(const std::string& op) {
        size_t eq_pos = op.find('=');
        if (eq_pos == std::string::npos)
            return "";

        std::string name = op.substr(0, eq_pos);
        std::string value = op.substr(eq_pos + 1);

        if (name == "resize") return "-resize " + value;
        if (name == "quality") return "-quality " + value;
        if (name == "rotate") return "-rotate " + value;
        if (name == "blur") return "-blur " + value;
        if (name == "crop") return "-crop " + value;
        if (name == "colorspace") return "-colorspace " + value;
        return "";
    }
};

} // namespace imaging

int main(int argc, char* argv[]) {
    if (argc < 4) return 1;

    imaging::ImagePipeline pipeline("s3cr3t_k3y_2024", "/var/img/workspace");
    auto result = pipeline.process(argv[1], argv[2], argv[3]);

    if (!result.success) {
        fprintf(stderr, "Error: %s\n", result.error.c_str());
        return 1;
    }
    printf("Output: %s\n", result.output_path.c_str());
    return 0;
}
